<script setup>
import { onMounted,reactive,ref } from 'vue'
import { ElTable,ElTableColumn,ElTag } from 'element-plus'
import { api,queryString } from '../../../shared/api.js'
import { money } from '../../../shared/demo.mjs'
import { useTask } from '../../../shared/use-task.js'
import Dialog from '../../../shared/Dialog.vue'
import Pager from '../components/Pager.vue'
import Feedback from '../components/Feedback.vue'
const {busy,error,notice,run}=useTask(),list=ref({items:[],page:1,total:0}),keyword=ref(''),editing=ref(false),editingId=ref(null)
const form=reactive({name:'',subtitle:'',category:'',description:'',image:'',price:'',active:true})
const load=async(page=1)=>list.value=await api(`/admin/products${queryString({page,keyword:keyword.value})}`)
onMounted(()=>run(()=>load()))
function open(product=null){editingId.value=product?.id||null;Object.assign(form,{name:product?.name||'',subtitle:product?.subtitle||'',category:product?.category||'',description:product?.description||'',image:product?.image||'',price:product?(product.priceUnits/100).toFixed(2):'',active:product?.active??true});editing.value=true;error.value=''}
async function save(){await run(async()=>{if(!/^\d+(\.\d{1,2})?$/.test(form.price)||Number(form.price)<=0)throw new Error('请输入有效的产品券价格，最多两位小数');const {price,...body}=form;await api(editingId.value?`/admin/products/${editingId.value}`:'/admin/products',{method:editingId.value?'PATCH':'POST',body:{...body,priceUnits:Math.round(Number(price)*100)}});editing.value=false;await load(list.value.page)},'商品已保存')}
async function toggle(p){await run(async()=>{await api(`/admin/products/${p.id}`,{method:'PATCH',body:{active:!p.active}});await load(list.value.page)},'上架状态已更新')}
</script>
<template><section class="panel"><Feedback :error="!editing?error:''" :notice="notice"/><div class="panel-heading"><form class="filter-bar" @submit.prevent="run(()=>load())"><input v-model.trim="keyword" aria-label="搜索商品" placeholder="搜索商品名称"><button class="secondary" :disabled="busy">查询</button></form><button class="primary" @click="open()">新增商品</button></div><ElTable :data="list.items" empty-text="暂无商品"><ElTableColumn label="商品" min-width="230"><template #default="{row}"><div class="admin-product"><img :src="row.image" :alt="row.name"><span><strong>{{ row.name }}</strong><small>{{ row.subtitle }} · {{ row.category }}</small></span></div></template></ElTableColumn><ElTableColumn label="产品券价格" min-width="130"><template #default="{row}">{{ money(row.priceUnits) }} 券</template></ElTableColumn><ElTableColumn label="状态" width="100"><template #default="{row}"><ElTag :type="row.active?'success':'info'">{{ row.active?'已上架':'已下架' }}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="150"><template #default="{row}"><button class="table-button" @click="open(row)">编辑</button><button class="table-button" :disabled="busy" @click="toggle(row)">{{ row.active?'下架':'上架' }}</button></template></ElTableColumn></ElTable><Pager :page="list.page" :total="list.total" :disabled="busy" @change="page=>run(()=>load(page))"/></section><Dialog v-if="editing" :title="editingId?'编辑商品':'新增商品'" @close="editing=false"><form class="form-stack" @submit.prevent="save"><label>商品名称<input v-model.trim="form.name" name="name" required maxlength="100"></label><label>规格说明<input v-model.trim="form.subtitle" maxlength="100"></label><label>分类<input v-model.trim="form.category" maxlength="60" placeholder="例如：日常洗护"></label><label>产品券价格<input v-model.trim="form.price" name="price" inputmode="decimal" required></label><label>图片地址<input v-model.trim="form.image" name="image" required maxlength="1000" placeholder="https://... 或 /images/... "></label><img v-if="form.image" class="image-preview" :src="form.image" alt="商品图片预览"><label>商品说明<textarea v-model="form.description" rows="4" maxlength="5000"></textarea></label><label class="checkbox-label"><input v-model="form.active" type="checkbox">上架商品</label><Feedback :error="error"/><button class="primary" type="submit" :disabled="busy">保存商品</button></form></Dialog></template>
